reply:
```turtle
@prefix ea:   <http://example.org/onto/assessment#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

<http://example.org/onto/assessment>
  a owl:Ontology ;
  rdfs:comment "Ontology of educational assessment, modeling classification axes (purpose, response type, referencing, formality, administering body, standardization, stakes, granularity), item/test types, validity, reliability, rubrics and related measurement concepts, as stated in the source corpus. Where the corpus presents conflicting classifications (coordinate lists vs. subordination, or explicit multi-membership), both claims are modeled and the tension is noted in comments." .

#################################################################
# TOP-LEVEL CLASSES
#################################################################

ea:Assessment a owl:Class ;
  rdfs:label "Assessment" ;
  skos:altLabel "educational assessment", "educational evaluation" ;
  rdfs:comment "The systematic process of documenting and using empirical data on knowledge, skill, attitudes, aptitude and beliefs to refine programs and improve student learning. Corpus notes 'assessment' is often used interchangeably with 'test' but is not limited to tests." .

ea:Test a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:label "Test" ;
  skos:altLabel "examination", "exam" ;
  rdfs:comment "An educational assessment intended to measure a test-taker's knowledge, skill, aptitude, physical fitness, or classification. Assessment is often used interchangeably with 'test' but is broader." .

ea:QualityAttribute a owl:Class ;
  rdfs:comment "Superclass for the quality attributes (validity, reliability) a good assessment should have, per the corpus: 'A good assessment has both validity and reliability.'" .

ea:Validity a owl:Class ; rdfs:subClassOf ea:QualityAttribute ;
  rdfs:comment "The degree to which an assessment measures what it is intended to measure." .

ea:Reliability a owl:Class ; rdfs:subClassOf ea:QualityAttribute ;
  rdfs:comment "The consistency of an assessment: a reliable assessment consistently achieves the same results with the same/similar cohort." .

ea:hasValidity a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:Validity .

ea:hasReliability a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:Reliability .

ea:hasReliabilityCoefficient a owl:DatatypeProperty ;
  rdfs:domain ea:Reliability ; rdfs:range xsd:decimal ;
  rdfs:comment "Reliability coefficient ranging from 0.00 (much error) to 1.00 (no error)." .

#################################################################
# AXIS 1: PURPOSE / TIMING  (Placement, Formative, Summative, Diagnostic)
#################################################################

ea:hasPurpose a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:PurposeCategory .

ea:PurposeCategory a owl:Class ;
  owl:disjointUnionOf ( ea:PlacementPurpose ea:FormativePurpose ea:SummativePurpose ea:DiagnosticPurpose ) .

ea:PlacementPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:FormativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:SummativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:DiagnosticPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .

ea:PlacementAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  skos:altLabel "pre-assessment", "initial assessment", "threshold knowledge test", "TKT", "placement evaluation", "placement testing" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:PlacementPurpose ] ) ] ;
  rdfs:comment "Used to place students according to prior achievement, level, or personal characteristics before instruction begins. Also referred to as 'initial assessment'." .

ea:FormativeAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  skos:altLabel "educative assessment", "assessment for learning", "classroom assessment", "formative evaluation", "formative feedback" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:FormativePurpose ] ) ] ;
  rdfs:comment "Carried out throughout a course to help learning; generally not used for grading. Robert Stake's analogy: 'When the cook tastes the soup, that's formative.'" .

ea:SummativeAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  skos:altLabel "assessment of learning", "summative evaluation" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:SummativePurpose ] ) ] ;
  rdfs:comment "Carried out at the end of a course/project to assign a grade. Robert Stake's analogy: 'When the guests taste the soup, that's summative.'" .

ea:DiagnosticAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  skos:altLabel "diagnostic testing" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:DiagnosticPurpose ] ) ] ;
  rdfs:subClassOf ea:FormativeAssessment ;
  rdfs:comment "TENSION: one passage lists diagnostic assessment as a coordinate alternative to formative/summative/placement (and hence disjoint, see AllDisjointClasses below), while another passage states 'A common form of formative assessment is diagnostic assessment', i.e. DiagnosticAssessment subClassOf FormativeAssessment. Both axioms are asserted as stated by the corpus, even though jointly they make DiagnosticAssessment logically unsatisfiable under strict disjointness." .

ea:SelfAssessment a owl:Class ;
  rdfs:subClassOf ea:DiagnosticAssessment ;
  rdfs:comment "Self-assessment is a form of diagnostic assessment in which students assess themselves." .

ea:ForwardLookingAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Asks those being assessed to consider themselves in hypothetical future situations." .

ea:InterimAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  skos:altLabel "benchmark assessment" ;
  rdfs:comment "Used periodically to determine whether students are on track for later summative tests. TENSION: corpus states 'some educators consider interim tests to be formative ... but others may consider them to be summative' -- both classifications are asserted below." .

ea:InterimAssessment rdfs:subClassOf [ a owl:Class ; owl:unionOf ( ea:FormativeAssessment ea:SummativeAssessment ) ] .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:PlacementAssessment ea:FormativeAssessment ea:SummativeAssessment ea:DiagnosticAssessment ) .

#################################################################
# AXIS 2: RESPONSE TYPE (Objective / Subjective) -- applies to Assessment AND Item
#################################################################

ea:ResponseTypeCategory a owl:Class ;
  owl:disjointUnionOf ( ea:ObjectiveResponseType ea:SubjectiveResponseType ) .
ea:ObjectiveResponseType a owl:Class ; rdfs:subClassOf ea:ResponseTypeCategory .
ea:SubjectiveResponseType a owl:Class ; rdfs:subClassOf ea:ResponseTypeCategory .

ea:hasResponseType a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain [ a owl:Class ; owl:unionOf ( ea:Assessment ea:Item ) ] ;
  rdfs:range ea:ResponseTypeCategory .

ea:ObjectiveAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasResponseType ; owl:someValuesFrom ea:ObjectiveResponseType ] ) ] ;
  rdfs:comment "A form of questioning that has a single correct answer." .

ea:SubjectiveAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasResponseType ; owl:someValuesFrom ea:SubjectiveResponseType ] ) ] ;
  rdfs:comment "A form of questioning that may have more than one correct answer or way of expressing it. Corpus notes some argue no assessment is truly 'objective' due to inherent biases." .

[] a owl:AllDisjointClasses ; owl:members ( ea:ObjectiveAssessment ea:SubjectiveAssessment ) .

#################################################################
# ITEMS (TEST QUESTIONS)
#################################################################

ea:Item a owl:Class ;
  rdfs:label "Item" ;
  skos:altLabel "question", "test item" ;
  rdfs:comment "'Item' is the general label; 'question' is a misnomer since many items are not phrased as questions (e.g., incomplete statements, analogies, equations)." .

ea:isItemOf a owl:ObjectProperty ;
  rdfs:domain ea:Item ; rdfs:range ea:Test ;
  owl:inverseOf ea:hasItem .

ea:hasItem a owl:ObjectProperty ;
  rdfs:domain ea:Test ; rdfs:range ea:Item .

ea:hasItemCount a owl:DatatypeProperty ;
  rdfs:domain ea:Test ; rdfs:range xsd:integer .

ea:hasStem a owl:DatatypeProperty ;
  rdfs:domain ea:Item ; rdfs:range xsd:string .

ea:Option a owl:Class ;
  rdfs:comment "A possible answer offered within a multiple-choice or multiple-response item." .

ea:hasOption a owl:ObjectProperty ;
  rdfs:domain ea:Item ; rdfs:range ea:Option .

ea:hasKey a owl:ObjectProperty ;
  rdfs:subPropertyOf ea:hasOption ;
  rdfs:domain ea:Item ; rdfs:range ea:Option ;
  rdfs:comment "The correct option(s) ('the key')." .

ea:hasDistractor a owl:ObjectProperty ;
  rdfs:subPropertyOf ea:hasOption ;
  rdfs:domain ea:Item ; rdfs:range ea:Option ;
  rdfs:comment "An incorrect option ('distractor')." .

ea:ObjectiveItem a owl:Class ;
  rdfs:subClassOf ea:Item ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Item
      [ a owl:Restriction ; owl:onProperty ea:hasResponseType ; owl:someValuesFrom ea:ObjectiveResponseType ] ) ] ;
  rdfs:comment "Objective question types include true/false, multiple-choice, multiple-response, and matching." .

ea:SubjectiveItem a owl:Class ;
  rdfs:subClassOf ea:Item ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Item
      [ a owl:Restriction ; owl:onProperty ea:hasResponseType ; owl:someValuesFrom ea:SubjectiveResponseType ] ) ] ;
  rdfs:comment "Subjective questions include extended-response and essay questions." .

[] a owl:AllDisjointClasses ; owl:members ( ea:ObjectiveItem ea:SubjectiveItem ) .

ea:TrueFalseItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem ;
  rdfs:comment "Requires a test taker to choose all answers that are appropriate (True/False family of multiple-choice questions)." .

ea:MultipleChoiceItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem ;
  skos:altLabel "MCQ", "multiple choice question", "objective response" ;
  rdfs:comment "Consists of a stem and alternative answers; only one answer may be keyed as correct (One-Best-Answer family)." ;
  rdfs:subClassOf [ a owl:Restriction ; owl:onProperty ea:hasKey ; owl:cardinality 1 ] .

ea:MultipleResponseItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem ;
  rdfs:comment "In contrast with multiple-choice items, more than one answer may be keyed as correct." ;
  rdfs:subClassOf [ a owl:Restriction ; owl:onProperty ea:hasKey ; owl:minQualifiedCardinality 2 ; owl:onClass ea:Option ] .

[] a owl:AllDisjointClasses ; owl:members ( ea:MultipleChoiceItem ea:MultipleResponseItem ) .

ea:MatchingItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem .

ea:FillInTheBlankItem a owl:Class ; rdfs:subClassOf ea:Item ;
  rdfs:comment "Provides identifying characteristics and requires the test taker to recall the correct term; may or may not provide a word bank." .

ea:ExtendedResponseItem a owl:Class ; rdfs:subClassOf ea:SubjectiveItem .

ea:EssayItem a owl:Class ; rdfs:subClassOf ea:SubjectiveItem ;
  skos:altLabel "free response question", "FRQ", "essay question" ;
  rdfs:comment "Requires test takers to respond to an open-ended prompt with a prose response." .

ea:ShortAnswerItem a owl:Class ; rdfs:subClassOf ea:SubjectiveItem ;
  rdfs:comment "Short-answer and essay tests better assess problem-solving and higher-order reasoning than multiple-choice." .

#################################################################
# AXIS 3: REFERENCING (Criterion / Norm / Ipsative)
#################################################################

ea:ReferencingCategory a owl:Class ;
  owl:disjointUnionOf ( ea:CriterionReferencing ea:NormReferencing ea:IpsativeReferencing ) .
ea:CriterionReferencing a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:NormReferencing a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:IpsativeReferencing a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .

ea:hasReferencing a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:ReferencingCategory .

ea:CriterionReferencedAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  skos:altLabel "standards-based assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:CriterionReferencing ] ) ] ;
  rdfs:comment "Occurs when candidates are measured against defined, objective criteria, e.g. a driving test." .

ea:NormReferencedAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  skos:altLabel "normative assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencing ] ) ] ;
  rdfs:comment "Relative to the student body taking it; colloquially 'grading on the curve'. E.g. the IQ test." .

ea:IpsativeAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:IpsativeReferencing ] ) ] ;
  rdfs:comment "Self-comparison either in the same domain over time or comparative to other domains within the same student." .

[] a owl:AllDisjointClasses ; owl:members ( ea:CriterionReferencedAssessment ea:NormReferencedAssessment ea:IpsativeAssessment ) .

ea:NormGroup a owl:Class ;
  skos:altLabel "norming group" ;
  rdfs:comment "The comparison group used to derive norm-referenced scores ('the norming process')." .

ea:hasNormGroup a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:NormReferencedAssessment ; rdfs:range ea:NormGroup .

ea:CriterionReferencedTest a owl:Class ;
  rdfs:subClassOf ea:Test ;
  skos:altLabel "CRT" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:CriterionReferencing ] ) ] .

ea:NormReferencedTest a owl:Class ;
  rdfs:subClassOf ea:Test ;
  skos:altLabel "NRT" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencing ] ) ] .

ea:hasCutScore a owl:DatatypeProperty ;
  rdfs:domain ea:CriterionReferencedTest ; rdfs:range xsd:decimal .

ea:MasteryTest a owl:Class ;
  rdfs:subClassOf ea:CriterionReferencedTest ;
  owl:equivalentClass [ owl:intersectionOf ( ea:CriterionReferencedTest
      [ a owl:Restriction ; owl:onProperty ea:hasCutScore ; owl:someValuesFrom xsd:decimal ] ) ] ;
  rdfs:comment "A criterion-referenced test that involves a cutscore; the examinee passes if their score exceeds it." .

ea:AchievementLevel a owl:Class ;
  owl:disjointUnionOf ( ea:BelowBasicLevel ea:BasicLevel ea:ProficientLevel ea:AdvancedLevel ) ;
  rdfs:comment "Broad achievement categories sometimes used to report criterion-referenced results." .
ea:BelowBasicLevel a owl:Class ; rdfs:subClassOf ea:AchievementLevel .
ea:BasicLevel a owl:Class ; rdfs:subClassOf ea:AchievementLevel .
ea:ProficientLevel a owl:Class ; rdfs:subClassOf ea:AchievementLevel .
ea:AdvancedLevel a owl:Class ; rdfs:subClassOf ea:AchievementLevel .

ea:hasAchievementLevel a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:CriterionReferencedTest ; rdfs:range ea:AchievementLevel .

#################################################################
# AXIS 4: FORMALITY (Formal / Informal)
#################################################################

ea:FormalityCategory a owl:Class ;
  owl:disjointUnionOf ( ea:FormalFormat ea:InformalFormat ) .
ea:FormalFormat a owl:Class ; rdfs:subClassOf ea:FormalityCategory .
ea:InformalFormat a owl:Class ; rdfs:subClassOf ea:FormalityCategory .

ea:hasFormality a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:FormalityCategory .

ea:FormalAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:FormalFormat ] ) ] ;
  rdfs:comment "Usually implies a written document (test, quiz, or paper); given a numerical score or grade." .

ea:InformalAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:InformalFormat ] ) ] ;
  rdfs:comment "Does not contribute to a final grade; may include observation, checklists, rubrics, portfolios, discussion." .

[] a owl:AllDisjointClasses ; owl:members ( ea:FormalAssessment ea:InformalAssessment ) .

#################################################################
# AXIS 5: ADMINISTERING BODY (Internal / External)
#################################################################

ea:AdministeringBodyCategory a owl:Class ;
  owl:disjointUnionOf ( ea:InternalBody ea:ExternalBody ) .
ea:InternalBody a owl:Class ; rdfs:subClassOf ea:AdministeringBodyCategory .
ea:ExternalBody a owl:Class ; rdfs:subClassOf ea:AdministeringBodyCategory .

ea:hasAdministeringBody a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:AdministeringBodyCategory .

ea:InternalAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasAdministeringBody ; owl:someValuesFrom ea:InternalBody ] ) ] ;
  rdfs:comment "Set and marked by the school (teachers)." .

ea:ExternalAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasAdministeringBody ; owl:someValuesFrom ea:ExternalBody ] ) ] ;
  rdfs:comment "Set by the governing body and marked by unbiased personnel." .

[] a owl:AllDisjointClasses ; owl:members ( ea:InternalAssessment ea:ExternalAssessment ) .

#################################################################
# AXIS 6: STANDARDIZATION (Standardized / Non-standardized)
#################################################################

ea:StandardizationCategory a owl:Class ;
  owl:disjointUnionOf ( ea:StandardizedCondition ea:NonStandardizedCondition ) .
ea:StandardizedCondition a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .
ea:NonStandardizedCondition a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .

ea:hasStandardization a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ; rdfs:range ea:StandardizationCategory .

ea:StandardizedTest a owl:Class ;
  rdfs:subClassOf ea:Test ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStandardization ; owl:someValuesFrom ea:StandardizedCondition ] ) ] ;
  rdfs:comment "Administered and scored in a consistent/standard manner for all test takers. Most standardized tests are summative assessments (stated as a general tendency, not a strict subsumption)." .

ea:NonStandardizedTest a owl:Class ;
  rdfs:subClassOf ea:Test ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStandardization ; owl:someValuesFrom ea:NonStandardizedCondition ] ) ] ;
  rdfs:comment "Flexible in scope and format, variable in difficulty; significantly different tests/conditions/grading across test takers." .

[] a owl:AllDisjointClasses ; owl:members ( ea:StandardizedTest ea:NonStandardizedTest ) .

#################################################################
# AXIS 7: STAKES (High-stakes / Low-stakes)
#################################################################

ea:StakesCategory a owl:Class ;
  owl:disjointUnionOf ( ea:HighStakesCondition ea:LowStakesCondition ) .
ea:HighStakesCondition a owl:Class ; rdfs:subClassOf ea:StakesCategory .
ea:LowStakesCondition a owl:Class ; rdfs:subClassOf ea:StakesCategory .

ea:hasStakes a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ; rdfs:range ea:StakesCategory .

ea:HighStakesTest a owl:Class ;
  rdfs:subClassOf ea:Test ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:HighStakesCondition ] ) ] ;
  rdfs:comment "A test with important consequences/rewards for good performance, used for accountability." .

ea:LowStakesTest a owl:Class ;
  rdfs:subClassOf ea:Test ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:LowStakesCondition ] ) ] ;
  rdfs:comment "Carries no significant public consequence, e.g. ordinary classroom quizzes." .

[] a owl:AllDisjointClasses ; owl:members ( ea:HighStakesTest ea:LowStakesTest ) .

ea:CompetitiveExamination a owl:Class ;
  rdfs:subClassOf ea:Test ;
  owl:equivalentClass [ owl:intersectionOf (
      ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencing ]
      [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:HighStakesCondition ]
  ) ] ;
  rdfs:comment "Norm-referenced, high-stakes tests in which candidates are ranked and top rankers selected, e.g. civil-service exams." .

#################################################################
# TENSION NOTE: multi-category membership vs. flat coordinate list
#################################################################

ea:Assessment rdfs:comment """CORPUS TENSION: one passage ('Assessment types include: Formative assessment, Summative assessment, Norm-referenced test, Criterion-referenced test, Performance-based assessments, Authentic assessment, Standardized test, Non-standardized test, High-stakes test, Competitive examinations') presents these as a single flat coordinate list of 'assessment types'. Elsewhere the corpus explicitly states 'Most tests can be classified on multiple categories. For example, a test can be both standardized and also a high-stakes test.' This ontology therefore does NOT assert these heterogeneous classes (which in fact span distinct axes: purpose, referencing, standardization, stakes, format) as pairwise disjoint, in line with the corpus's explicit statement of overlap, even though the surface list suggests a coordinate partition.""" .

#################################################################
# PERFORMANCE / AUTHENTIC / CONTINUOUS / PORTFOLIO ASSESSMENT
#################################################################

ea:PerformanceBasedAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  skos:closeMatch ea:SummativeAssessment ;
  rdfs:comment "Similar to summative assessment in focusing on achievement; a well-defined task is identified and students create, produce, or do something, often with real-world application." .

ea:AuthenticAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  skos:closeMatch ea:PerformanceBasedAssessment ;
  rdfs:comment "Measurement of accomplishments within a realistic, practical context relevant outside the school setting. Corpus states performance assessments 'may also be called authentic assessments', yet also lists them as separate coordinate assessment types -- both treatments are retained (closeMatch plus distinct class)." .

ea:OutcomeFormatCategory a owl:Class ;
  owl:disjointUnionOf ( ea:ProductOutcome ea:PerformanceOutcome ) ;
  rdfs:comment "Performance formats are further classified into products and performances." .
ea:ProductOutcome a owl:Class ; rdfs:subClassOf ea:OutcomeFormatCategory .
ea:PerformanceOutcome a owl:Class ; rdfs:subClassOf ea:OutcomeFormatCategory .

ea:hasOutcomeFormat a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:PerformanceBasedAssessment ; rdfs:range ea:OutcomeFormatCategory .

ea:ProductBasedAssessment a owl:Class ;
  rdfs:subClassOf ea:PerformanceBasedAssessment ;
  owl:equivalentClass [ owl:intersectionOf ( ea:PerformanceBasedAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasOutcomeFormat ; owl:someValuesFrom ea:ProductOutcome ] ) ] ;
  rdfs:comment "Results in a product such as a painting, portfolio, paper, or exhibition." .

ea:PerformanceOutcomeAssessment a owl:Class ;
  rdfs:subClassOf ea:PerformanceBasedAssessment ;
  owl:equivalentClass [ owl:intersectionOf ( ea:PerformanceBasedAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasOutcomeFormat ; owl:someValuesFrom ea:PerformanceOutcome ] ) ] ;
  rdfs:comment "Consists of a performance, such as a speech, athletic skill, musical recital, or reading." .

[] a owl:AllDisjointClasses ; owl:members ( ea:ProductBasedAssessment ea:PerformanceOutcomeAssessment ) .

ea:PerformanceTest a owl:Class ;
  rdfs:subClassOf ea:Test ;
  rdfs:comment "Requires an examinee to actually perform a task or activity rather than answer questions about it, e.g. a behind-the-wheel driving test." .

ea:SimulationTest a owl:Class ; rdfs:subClassOf ea:PerformanceTest ;
  rdfs:comment "A performance test implemented as a computerized simulation." .

ea:WorkSample a owl:Class ; rdfs:subClassOf ea:PerformanceTest ;
  rdfs:comment "Term used for a performance test when used for personnel selection." .

ea:ContinuousAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Evaluates a student's progress throughout a prescribed course; an alternative to the final examination system; often includes formative assessment." .

ea:AssessmentInstrument a owl:Class ;
  rdfs:comment "An instrument or artifact used to carry out an assessment." .

ea:Portfolio a owl:Class ; rdfs:subClassOf ea:AssessmentInstrument ;
  rdfs:comment "A compilation of academic work and other educational evidence assembled over time." .

ea:EPortfolio a owl:Class ; rdfs:subClassOf ea:Portfolio ;
  skos:altLabel "digital portfolio", "e-portfolio" .

ea:hasAssessmentInstrument a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:AssessmentInstrument .

ea:PortfolioAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasAssessmentInstrument ; owl:someValuesFrom ea:Portfolio ] ) ] ;
  rdfs:comment "Evaluates coursework quality, progress and achievement using a portfolio." .

#################################################################
# GRANULARITY AXIS
#################################################################

ea:GranularityLevel a owl:Class ;
  owl:disjointUnionOf ( ea:LearnerGranularity ea:LearningCommunityGranularity ea:CourseGranularity
                        ea:ProgramGranularity ea:InstitutionGranularity ea:EducationalSystemGranularity ) ;
  rdfs:comment "Assessment can focus on the individual learner, the learning community, a course, an academic program, the institution, or the educational system as a whole (granularity)." .
ea:LearnerGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:LearningCommunityGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:CourseGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:ProgramGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:InstitutionGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:EducationalSystemGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .

ea:hasGranularity a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:GranularityLevel .

#################################################################
# VALIDITY TYPES
#################################################################

ea:ContentValidity a owl:Class ; rdfs:subClassOf ea:Validity ;
  skos:altLabel "logical validity" ;
  rdfs:comment "Whether the content of the test covers a representative sample of the behavior domain to be measured." .

ea:CriterionValidity a owl:Class ; rdfs:subClassOf ea:Validity ;
  skos:altLabel "criterion-related validity" ;
  rdfs:comment "The correlation between the test and a criterion variable taken as representative of the construct." .

ea:ConstructValidity a owl:Class ; rdfs:subClassOf ea:Validity ;
  rdfs:comment "The extent to which operationalizations of a construct measure the construct as defined by theory." .

ea:FaceValidity a owl:Class ; rdfs:subClassOf ea:Validity ;
  rdfs:comment "Whether a test appears, on its face, to measure what it purports to measure." .

ea:ConsequentialValidity a owl:Class ; rdfs:subClassOf ea:Validity .

ea:SubjectMatterValidity a owl:Class ; rdfs:subClassOf ea:Validity ;
  rdfs:comment "Widely used in education; predicts the score a student would get on a similar test with different questions. Distinguished by the corpus from predictive validity (used in the workplace, predicts performance)." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:ContentValidity ea:CriterionValidity ea:ConstructValidity ea:FaceValidity ea:ConsequentialValidity ) .

ea:ContentValidity rdfs:subClassOf ea:ConstructValidity .
ea:CriterionValidity rdfs:subClassOf ea:ConstructValidity .
ea:ConstructValidity rdfs:comment "Modern validity theory (Messick) treats construct validity as subsuming all other types of validity evidence, including content and criterion validity. TENSION: this subsumption is asserted together with the coordinate, pairwise-disjoint listing of validity types ('content validity ... criterion validity ... construct validity ... Others are: consequential validity, face validity') found elsewhere in the corpus." .

ea:TimingCategory a owl:Class ;
  owl:disjointUnionOf ( ea:ConcurrentTiming ea:PredictiveTiming ) .
ea:ConcurrentTiming a owl:Class ; rdfs:subClassOf ea:TimingCategory .
ea:PredictiveTiming a owl:Class ; rdfs:subClassOf ea:TimingCategory .

ea:hasMeasurementTiming a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:CriterionValidity ; rdfs:range ea:TimingCategory .

ea:ConcurrentValidity a owl:Class ;
  rdfs:subClassOf ea:CriterionValidity ;
  owl:equivalentClass [ owl:intersectionOf ( ea:CriterionValidity
      [ a owl:Restriction ; owl:onProperty ea:hasMeasurementTiming ; owl:someValuesFrom ea:ConcurrentTiming ] ) ] ;
  rdfs:comment "Test data and criterion data are collected at the same time." .

ea:PredictiveValidity a owl:Class ;
  rdfs:subClassOf ea:CriterionValidity ;
  owl:equivalentClass [ owl:intersectionOf ( ea:CriterionValidity
      [ a owl:Restriction ; owl:onProperty ea:hasMeasurementTiming ; owl:someValuesFrom ea:PredictiveTiming ] ) ] ;
  rdfs:comment "Test data are collected first to predict criterion data collected at a later time." .

[] a owl:AllDisjointClasses ; owl:members ( ea:ConcurrentValidity ea:PredictiveValidity ) .

ea:ConvergentValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity ;
  rdfs:comment "The degree to which two measures of theoretically related constructs are, in fact, related." .
ea:DiscriminantValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity ;
  rdfs:comment "Whether concepts/measurements that should be unrelated are, in fact, unrelated. Convergent and discriminant validity are 'the two subtypes of validity that make up construct validity'." .

[] a owl:AllDisjointClasses ; owl:members ( ea:ConvergentValidity ea:DiscriminantValidity ) .

#################################################################
# RELIABILITY TYPES
#################################################################

ea:StudentRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  rdfs:comment "Can include personal problems, sickness, or fatigue (one of the four stated types of reliability)." .
ea:RaterRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  rdfs:comment "Includes bias and subjectivity." .
ea:TestAdministrationRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  rdfs:comment "Concerns the conditions of the test-taking process." .
ea:TestRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  rdfs:comment "Related to the nature of the test itself." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:StudentRelatedReliability ea:RaterRelatedReliability ea:TestAdministrationRelatedReliability ea:TestRelatedReliability ) .

ea:ReliabilityEstimationMethod a owl:Class ; rdfs:subClassOf ea:Reliability ;
  rdfs:comment "General classes of reliability estimates (estimation methods), distinct from the four sources-of-error types above." .

ea:InterRaterReliability a owl:Class ; rdfs:subClassOf ea:ReliabilityEstimationMethod ;
  rdfs:comment "Degree of agreement between two or more raters in their appraisals." .

ea:TestRetestReliability a owl:Class ; rdfs:subClassOf ea:ReliabilityEstimationMethod ;
  skos:altLabel "repeatability" ;
  rdfs:comment "Degree to which test scores are consistent from one administration to the next, with a single rater/instrument." .

ea:IntraRaterReliability a owl:Class ; rdfs:subClassOf ea:TestRetestReliability .

ea:InterMethodReliability a owl:Class ; rdfs:subClassOf ea:ReliabilityEstimationMethod ;
  skos:altLabel "parallel-forms reliability" ;
  rdfs:comment "Degree to which test scores are consistent when there is variation in the methods or instruments used." .

ea:SplitHalfReliability a owl:Class ; rdfs:subClassOf ea:InterMethodReliability ;
  rdfs:comment "Treats the two halves of a measure as alternate forms; estimate is stepped up via the Spearman-Brown formula." .

ea:InternalConsistencyReliability a owl:Class ; rdfs:subClassOf ea:ReliabilityEstimationMethod ;
  rdfs:comment "Assesses the consistency of results across items within a test, e.g. via Cronbach's alpha." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:InterRaterReliability ea:TestRetestReliability ea:InterMethodReliability ea:InternalConsistencyReliability ) .

#################################################################
# CLASSICAL TEST THEORY: SCORES AND ERROR
#################################################################

ea:TrueScore a owl:Class ;
  rdfs:comment "The replicable feature of the concept being measured (T); recurs across measurement occasions absent error." .

ea:ObservedScore a owl:Class ;
  rdfs:comment "The observed test score (X); X = T + E." .

ea:MeasurementError a owl:Class ;
  rdfs:comment "Discrepancy between the observed test score and the corresponding true score (E), or more generally the difference between a reported figure and reality in educational data." .

ea:hasTrueScoreComponent a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:ObservedScore ; rdfs:range ea:TrueScore .

ea:hasErrorComponent a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:ObservedScore ; rdfs:range ea:MeasurementError .

ea:TestScoreMeasurementError a owl:Class ; rdfs:subClassOf ea:MeasurementError ;
  rdfs:comment "The difference between what a test score indicates and a student's actual knowledge/abilities." .

ea:DataReportingMeasurementError a owl:Class ; rdfs:subClassOf ea:MeasurementError ;
  rdfs:comment "Errors introduced when collecting and calculating data-based reports, figures, and statistics about schools and students." .

[] a owl:AllDisjointClasses ; owl:members ( ea:TestScoreMeasurementError ea:DataReportingMeasurementError ) .

ea:RandomError a owl:Class ; rdfs:subClassOf ea:TestScoreMeasurementError ;
  rdfs:comment "Assumed to be equally likely positive or negative; uncorrelated with true scores." .
ea:SystematicError a owl:Class ; rdfs:subClassOf ea:TestScoreMeasurementError .

[] a owl:AllDisjointClasses ; owl:members ( ea:RandomError ea:SystematicError ) .

#################################################################
# RUBRICS AND GRADING METHODS
#################################################################

ea:Rubric a owl:Class ;
  rdfs:subClassOf ea:AssessmentInstrument ;
  rdfs:comment "A scoring guide used to evaluate the quality of students' constructed responses (Popham); contains criteria, quality definitions, and a scoring strategy." .

ea:hasRubric a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:Rubric .

ea:RubricTypeCategory a owl:Class ;
  owl:disjointUnionOf ( ea:HolisticRubricType ea:AnalyticRubricType ea:DevelopmentalRubricType ) .
ea:HolisticRubricType a owl:Class ; rdfs:subClassOf ea:RubricTypeCategory .
ea:AnalyticRubricType a owl:Class ; rdfs:subClassOf ea:RubricTypeCategory .
ea:DevelopmentalRubricType a owl:Class ; rdfs:subClassOf ea:RubricTypeCategory .

ea:hasRubricType a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Rubric ; rdfs:range ea:RubricTypeCategory .

ea:HolisticRubric a owl:Class ;
  rdfs:subClassOf ea:Rubric ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Rubric
      [ a owl:Restriction ; owl:onProperty ea:hasRubricType ; owl:someValuesFrom ea:HolisticRubricType ] ) ] ;
  rdfs:comment "Provides an overall rating for a piece of work, considering all aspects." .

ea:AnalyticRubric a owl:Class ;
  rdfs:subClassOf ea:Rubric ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Rubric
      [ a owl:Restriction ; owl:onProperty ea:hasRubricType ; owl:someValuesFrom ea:AnalyticRubricType ] ) ] ;
  rdfs:comment "Evaluates various dimensions or components separately." .

ea:DevelopmentalRubric a owl:Class ;
  rdfs:subClassOf ea:Rubric ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Rubric
      [ a owl:Restriction ; owl:onProperty ea:hasRubricType ; owl:someValuesFrom ea:DevelopmentalRubricType ] ) ] ;
  rdfs:subClassOf ea:AnalyticRubric ;
  rdfs:comment "TENSION: corpus states 'Rubrics can be classified as holistic, analytic, or developmental' (a coordinate three-way list, hence disjoint below) but then states 'Developmental rubrics, a subset of analytical rubrics' (i.e. DevelopmentalRubric subClassOf AnalyticRubric). Both axioms are retained." .

[] a owl:AllDisjointClasses ; owl:members ( ea:HolisticRubric ea:AnalyticRubric ea:DevelopmentalRubric ) .

ea:ComplexAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasRubric ; owl:someValuesFrom ea:Rubric ] ) ] ;
  rdfs:comment "Requires a rubric and an expert examiner, e.g. a thesis or funding proposal; complexity is due to format implicitness." .

ea:GradingMethod a owl:Class ;
  rdfs:comment "A method of judging/scoring student work." .

ea:HolisticGrading a owl:Class ; rdfs:subClassOf ea:GradingMethod ;
  skos:altLabel "holistic scoring", "nonreductionist grading" ;
  rdfs:comment "Bases a grade on a paper's overall quality, treating the composition as a whole." .

ea:AnalyticGrading a owl:Class ; rdfs:subClassOf ea:GradingMethod ;
  rdfs:comment "Involves criterion-by-criterion judgments, contrasted with holistic grading." .

[] a owl:AllDisjointClasses ; owl:members ( ea:HolisticGrading ea:AnalyticGrading ) .

ea:TraitInformedScoring a owl:Class ; rdfs:subClassOf ea:GradingMethod ;
  rdfs:comment "Trains raters to score to a scoring guide across multiple traits; comes close to analytic scoring but remains holistic at heart." .

#################################################################
# LEARNING OUTCOMES AND CONSTRUCTIVE ALIGNMENT
#################################################################

ea:LearningOutcome a owl:Class ;
  rdfs:comment "Statements about what students should be able to do by the end of a teaching session." .

ea:hasLearningOutcome a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:LearningOutcome .

ea:IntendedLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome ;
  rdfs:comment "Equated with 'aims' of a course." .
ea:MeasuredLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome ;
  rdfs:comment "Equated with 'objectives', i.e. outcomes that are measured." .
ea:UnintendedLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome ;
  rdfs:comment "Beneficial outcomes that were neither planned nor sought but are observed." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:IntendedLearningOutcome ea:MeasuredLearningOutcome ea:UnintendedLearningOutcome ) .

ea:ConstructiveAlignment a owl:Class ;
  rdfs:comment "A principle (Biggs) for devising teaching/learning activities and assessment tasks that directly address intended learning outcomes." .

#################################################################
# SPECIFIC NAMED TESTS
#################################################################

ea:Quiz a owl:Class ;
  rdfs:subClassOf ea:Test, ea:FormativeAssessment ;
  rdfs:comment "A brief assessment covering a small amount of material; usually low stakes, generally used formatively, though it 'can make a significant part of the final course grade' (tension with pure-formative, ungraded characterization)." .

ea:MidtermExam a owl:Class ;
  rdfs:subClassOf ea:Test ;
  rdfs:subClassOf [ a owl:Class ; owl:unionOf ( ea:FormativeAssessment ea:SummativeAssessment ) ] ;
  rdfs:comment "Given near the middle of a grading term. TENSION: one passage states 'Midterm exams are a type of formative or summative assessment' (modeled as a union restriction), while another passage lists 'a midterm exam' directly as an example of a summative assessment." .

ea:MidtermExam rdfs:subClassOf ea:SummativeAssessment .

ea:FinalExam a owl:Class ;
  rdfs:subClassOf ea:Test, ea:SummativeAssessment ;
  skos:altLabel "final", "finals" ;
  rdfs:comment "Makes a final review of topics covered; given as an example of a summative assessment ('a final project')." .

#################################################################
# TEACHER EVALUATION / VALUE-ADDED / SCORE INFLATION
#################################################################

ea:TeacherEvaluation a owl:Class ;
  rdfs:subClassOf ea:SummativeAssessment ;
  rdfs:comment "Summative assessment can be used to refer to assessment of educational faculty by their supervisor." .

ea:ValueAddedMeasure a owl:Class ;
  rdfs:subClassOf ea:TeacherEvaluation ;
  skos:altLabel "growth measure" ;
  rdfs:comment "Uses statistical algorithms and standardized-test results to estimate a teacher's effect on student learning." .

ea:StudentGrowthMeasure a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "A related but distinct method of using student test scores to quantify academic achievement and growth; does not attempt to isolate teacher effect the way value-added measures do." .

ea:ScoreInflation a owl:Class ;
  rdfs:comment "Results when student scores increase without genuine improvement in learning, often associated with high-stakes testing." .

#################################################################
# COMPETENCY-BASED / PROFICIENCY-BASED LEARNING
#################################################################

ea:CompetencyBasedLearning a owl:Class ;
  skos:altLabel "proficiency-based learning", "mastery-based learning", "outcome-based learning", "standards-based learning" ;
  rdfs:comment "Systems of instruction, assessment, grading and reporting based on students demonstrating learning of expected knowledge/skills; closely associated with criterion-referenced testing." .
